    // Extract the actual output before assertion to avoid Sensitive Equality smell
    String actualOutput = out.toString();
    //@formatter:off
    assertEquals(
            "usage: foobar" + EOL +
            EOL +
            "Header" + EOL +
            EOL +
            "Footer" + EOL,
            actualOutput);
    //@formatter:on
}

smells.SensitiveEquality:
Extract the out.toString() call into a separate variable before the assertion, e.g.,
String actualValue = out.toString();
then use assertEquals(expectedString, actualValue);

